<?php
declare(strict_types=1);namespace Vendi\Reports;use PDO;use Vendi\Branches\BranchClock;
final class ReportService{public function __construct(private PDO$db){}
 public function sales(int$b,int$branch,string$fromDate,string$toDate):array{$clock=new BranchClock($this->db);[$from]=$clock->utcRangeForLocalDate($b,$branch,$fromDate);[, $to]=$clock->utcRangeForLocalDate($b,$branch,$toDate);$q=$this->db->prepare("SELECT COUNT(*) tickets,COALESCE(SUM(total),0) sales,COALESCE(SUM(cost_total),0) cost,COALESCE(SUM(discount),0) discounts,COALESCE(SUM(tax),0) tax,COALESCE(AVG(total),0) average_ticket,COALESCE(MAX(total),0) peak_sale FROM sales WHERE business_id=? AND branch_id=? AND status='completed' AND completed_at_utc>=? AND completed_at_utc<?");$q->execute([$b,$branch,$from,$to]);$summary=$q->fetch();$summary['profit']=(float)$summary['sales']-(float)$summary['cost'];$p=$this->db->prepare("SELECT COALESCE(pm.name,p.method) method,COALESCE(SUM(p.amount-p.change_amount),0) total FROM payments p JOIN sales s ON s.id=p.sale_id LEFT JOIN payment_methods pm ON pm.id=p.payment_method_id WHERE s.business_id=? AND s.branch_id=? AND s.status='completed' AND s.completed_at_utc>=? AND s.completed_at_utc<? GROUP BY COALESCE(pm.name,p.method) ORDER BY total DESC");$p->execute([$b,$branch,$from,$to]);$top=$this->db->prepare("SELECT si.description,SUM(si.qty) qty,SUM(si.line_total) sales FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE s.business_id=? AND s.branch_id=? AND s.status='completed' AND s.completed_at_utc>=? AND s.completed_at_utc<? GROUP BY si.product_id,si.description ORDER BY sales DESC LIMIT 15");$top->execute([$b,$branch,$from,$to]);return['summary'=>$summary,'payments'=>$p->fetchAll(),'top_products'=>$top->fetchAll(),'timezone'=>$clock->timezone($b,$branch)->getName()];}
}